<script setup lang="ts">
import { computed,onMounted,ref } from "vue";import { Pige360SessionClient,type ApiProblem } from "@pige360/auth";type Row=Record<string,any>;const api=new Pige360SessionClient();const ready=ref(false),auth=ref(false),busy=ref(false),error=ref(""),notice=ref(""),email=ref(""),password=ref("");const ctx=ref<Row>({branding:{},entries:[]});const school=computed(()=>ctx.value.branding?.short_name||ctx.value.branding?.trade_name||ctx.value.branding?.legal_name||"Instituição");function msg(e:unknown){const p=(e as Error&{problem?:ApiProblem})?.problem;return p?.detail||(e instanceof Error?e.message:"Erro inesperado");}function apply(){document.documentElement.style.setProperty("--brand-primary",ctx.value.branding?.primary_color||"#006D77");document.documentElement.style.setProperty("--brand-secondary",ctx.value.branding?.secondary_color||"#0D1B2A");document.title=`${school.value} — Ponto`;}
async function load(){ctx.value=await api.request<Row>("/portal/timeclock/me");apply();}async function boot(){try{await api.initialize();auth.value=!!api.tokens;if(auth.value)await load();}catch(e){error.value=msg(e);}finally{ready.value=true;}}async function login(){busy.value=true;try{await api.login(email.value,password.value);auth.value=true;await load();}catch(e){error.value=msg(e);}finally{busy.value=false;}}async function logout(){await api.logout();auth.value=false;}
async function clock(event_type:string){busy.value=true;error.value="";try{await api.request("/timekeeping/me/entries",{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":`clock-${event_type}-${crypto.randomUUID()}`},body:JSON.stringify({event_type,origin:"app",device_id:"pige360-timeclock"})});notice.value="Registro efetuado com sucesso.";await load();}catch(e){error.value=msg(e);}finally{busy.value=false;}}const events=[['clock_in','Entrada'],['break_out','Saída intervalo'],['break_in','Retorno intervalo'],['clock_out','Saída']] as const;onMounted(boot);
</script>
<template><div v-if="!ready" class="center">Inicializando ponto…</div><div v-else-if="!auth" class="login-page"><form class="login-card" @submit.prevent="login"><div class="mark">◷</div><span class="eyebrow">Controle de ponto</span><h1>Identificação do colaborador</h1><label>E-mail<input v-model="email" type="email" required></label><label>Senha<input v-model="password" type="password" required></label><p v-if="error" class="flash error">{{error}}</p><button class="primary">Entrar</button></form></div><div v-else class="mobile-shell"><header><div class="brand"><div class="mark">◷</div><div><strong>{{school}}</strong><small>Registro de jornada</small></div></div><button class="ghost" @click="logout">Sair</button></header><main><div v-if="error" class="flash error">{{error}}</div><div v-if="notice" class="flash success">{{notice}}</div><section class="welcome"><span class="eyebrow light">Colaborador</span><h1>{{ctx.person?.social_name||ctx.person?.full_name}}</h1><p>{{ctx.employee?.employee_number}} · {{ctx.employee?.position}}</p></section><section class="clock-grid"><button v-for="e in events" :key="e[0]" class="clock-action" :disabled="busy" @click="clock(e[0])"><span>◷</span><strong>{{e[1]}}</strong><small>Registrar agora</small></button></section><section class="panel"><div class="section-title"><h2>Últimos registros</h2><span>{{ctx.entries?.length||0}}</span></div><div class="list-row" v-for="entry in ctx.entries" :key="entry.id"><div><strong>{{entry.event_type}}</strong><span>{{new Date(entry.occurred_at).toLocaleString('pt-BR')}}</span></div><small>{{entry.origin}} · {{entry.state}}</small></div><p v-if="!ctx.entries?.length" class="empty">Nenhum registro de jornada.</p></section></main></div></template>
